package com.bank.validation;

import java.util.logging.Logger;

// Validates numeric fields on National Bank of India forms.
public class InputValidator {
    private static final Logger log = Logger.getLogger(InputValidator.class.getName());

    // True only if the string is non-empty and every char is a (Unicode) digit.
    public boolean isAllDigits(String s) {
        if (s == null || s.isEmpty()) {
            log.fine("Empty or null field is not all-digits");
            return false;                        // empty is NOT valid by convention
        }
        for (int i = 0; i < s.length(); i++) {
            if (!Character.isDigit(s.charAt(i))) {
                final int idx = i;
                log.fine(() -> "Non-digit at index " + idx + " in '" + s + "'");
                return false;                    // fail fast
            }
        }
        return true;
    }

    // Stricter: only ASCII digits '0'..'9', rejects non-ASCII numerals.
    public boolean isAsciiDigitsOnly(String s) {
        if (s == null || s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;                    // outside ASCII digit range
            }
        }
        return true;
    }
}
