package com.bank.validation;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: validate account-number and amount fields.
public class ValidationDemo {
    private static final Logger log = Logger.getLogger(ValidationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        InputValidator validator = new InputValidator();

        String rajeshAccount = "2001";       // clean
        String badAmount      = "50 000";     // stray space
        String devanagari     = "\u0967\u0968\u0969"; // Devanagari digits 1,2,3

        log.info(() -> "Rajesh account '" + rajeshAccount + "' all-digits? "
                + validator.isAllDigits(rajeshAccount));
        log.info(() -> "Amount '" + badAmount + "' all-digits? "
                + validator.isAllDigits(badAmount));
        log.info(() -> "Devanagari string Unicode all-digits? "
                + validator.isAllDigits(devanagari));
        log.info(() -> "Devanagari string ASCII-only digits? "
                + validator.isAsciiDigitsOnly(devanagari));
    }
}
